export interface HeaderRightProps {
  locale: Locale;
  onLocaleChange: (locale: Locale) => void;

  /** Authenticated user. When omitted, a Sign in button renders instead. */
  user?: UserMenuUser;
  /** Rows shown in the UserMenu dropdown. Required when `user` is present. */
  userMenuItems?: UserMenuItem[];
  /** If provided, renders a Suites dropdown button before the search pill. */
  suites?: {
    entries: SuiteEntry[];
    /** Translated trigger label (e.g. "Suítes"). */
    label: string;
    /** Translated aria-label (e.g. "Open Suites menu"). */
    ariaLabel: string;
    /** Translated word for tooltips: "{N} {appsLabel}". */
    appsLabel: string;
  };
  /** If provided, renders a cog icon button for opening preferences/settings. */
  onPreferences?: () => void;
  /** If provided, renders a bell icon with an unread-count badge. */
  notifications?: {
    /** 0 = no badge; 1+ = "1", "2", … "9+". */
    count: number;
    /** The click event is forwarded so the consumer can anchor a popover off
     * the bell's bounding rect. */
    onClick: (event: React.MouseEvent<HTMLButtonElement>) => void;
    /** aria-label + tooltip — caller must pass a translated string. */
    label: string;
  };
  /** If provided, renders a search pill that opens the command palette (⌘K). */
  onOpenPalette?: () => void;
  /** Label for the command-palette pill's accessible name (e.g. "Search"). */
  paletteLabel?: string;
  /** If provided (and no user), renders a "Sign in" button that calls this handler. */
  onSignIn?: () => void;
  /** Label for the Sign in button (default: "Sign in"). */
  signInLabel?: string;

  /** Slot before the locale toggle — e.g. <LiveIndicator count={9} /> */
  before?: React.ReactNode;
  /** Slot after the user menu — e.g. extra app-specific chrome */
  after?: React.ReactNode;
}

/**
 * Standard right-hand side of the app top bar: locale toggle, theme toggle,
 * optional preferences cog, and either a UserMenu (authenticated) or a
 * Sign in button (unauthenticated).
 *
 * Used by both the home screen and every remote app's Layout so headers
 * stay visually identical across the product.
 */
/**
 * Platform-aware modifier key label. macOS → ⌘, Windows/Linux/ChromeOS → Ctrl.
 * Uses the modern `userAgentData` API with a fallback to the (now-deprecated)
 * `navigator.platform`. SSR-safe — returns the non-Mac label on the server.
 */
function getModKeyLabel(): string {
  if (typeof navigator === 'undefined') return 'Ctrl';
  type NavigatorWithUAData = Navigator & { userAgentData?: { platform?: string } };
  const nav = navigator as NavigatorWithUAData;
  const platform =
    nav.userAgentData?.platform ??
    navigator.platform ??
    navigator.userAgent ??
    '';
  return /Mac|iPod|iPhone|iPad/i.test(platform) ? '⌘' : 'Ctrl';
}

export function HeaderRight({
  locale,
  onLocaleChange,
  user,
  userMenuItems = [],
  suites,
  onPreferences,
  notifications,
  onOpenPalette,
  paletteLabel = 'Search',
  onSignIn,
  signInLabel = 'Sign in',
  before,
  after,
}: HeaderRightProps) {
  const mod = getModKeyLabel();
  // ⌘ glyphs read tight without a separator; "Ctrl" needs a '+' for clarity.
  const kbdLabel = mod === '⌘' ? `${mod}K` : `${mod}+K`;
  return (
    <Row>
      {before}
      {suites && suites.entries.length > 0 && (
        <SuitesMenu
          label={suites.label}
          ariaLabel={suites.ariaLabel}
          appsLabel={suites.appsLabel}
          suites={suites.entries}
        />
      )}
      {onOpenPalette && (
        <SearchPill
          onClick={onOpenPalette}
          aria-label={paletteLabel}
          title={`${paletteLabel} (${kbdLabel})`}
        >
          <Search size={14} />
          <span className="kbd">{kbdLabel}</span>
        </SearchPill>
      )}
      <LocaleToggle locale={locale} onChange={onLocaleChange} />
      <ThemeToggle />
      {notifications && (
        <BellWrap>
          <IconCircle
            onClick={notifications.onClick}
            aria-label={notifications.label}
            title={notifications.label}
          >
            <Icon name="bell" size={16} />
          </IconCircle>
          {notifications.count > 0 && (
            <BellDot aria-hidden="true">
              {notifications.count > 9 ? '9+' : notifications.count}
            </BellDot>
          )}
        </BellWrap>
      )}
      {onPreferences && (
        <IconCircle onClick={onPreferences} aria-label="User preferences" title="Preferences">
          <UserCog size={16} />
        </IconCircle>
      )}
      {user ? (
        <UserMenu user={user} items={userMenuItems} />
      ) : onSignIn ? (
        <SignInBtn onClick={onSignIn} aria-label={signInLabel}>
          <LogIn size={14} />
          {signInLabel}
        </SignInBtn>
      ) : null}
      {after}
    </Row>
  );
}
