export type IconName = keyof typeof ICON_PATHS;

export interface IconProps extends Omit<React.SVGProps<SVGSVGElement>, 'name'> {
  name: IconName;
  /** Edge length in pixels. Default 18. */
  size?: number;
  /** Override stroke width. Default 1.5 (matches gallery). */
  strokeWidth?: number;
}

/**
 * Renders an Atlantis design-system icon by name.
 *
 * ```tsx
 * <Icon name="bell" size={16} />
 * <Icon name="sparkle" size={20} aria-label="Ask Atlantis" />
 * ```
 *
 * Decorative icons should pass `aria-hidden`; meaningful icons should pass
 * `aria-label` (translated by the caller).
 */
export function Icon({
  name,
  size = 18,
  strokeWidth = 1.5,
  ...rest
}: IconProps) {
  const inner = ICON_PATHS[name];
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={strokeWidth}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden={rest['aria-label'] ? undefined : true}
      {...rest}
      // eslint-disable-next-line react/no-danger
      dangerouslySetInnerHTML={{ __html: inner }}
    />
  );
}
