import React, { useState } from 'react';
import styled from '@emotion/styled';
import { keyframes } from '@emotion/react';
import { theme } from '../theme';

const fadeIn = keyframes`
  from { opacity: 0; transform: translateY(-50%) translateX(-6px); }
  to   { opacity: 1; transform: translateY(-50%) translateX(0); }
`;

const Box = styled.div`
  position: absolute;
  left: calc(100% + 10px);
  top: 50%;
  transform: translateY(-50%);
  pointer-events: none;
  z-index: 200;
  animation: ${fadeIn} 0.16s cubic-bezier(0.4, 0, 0.2, 1) forwards;

  /* Arrow pointing left */
  &::before {
    content: '';
    position: absolute;
    right: 100%;
    top: 50%;
    transform: translateY(-50%);
    border: 5px solid transparent;
    border-right-color: ${theme.colors.accentMuted};
  }
  &::after {
    content: '';
    position: absolute;
    right: calc(100% - 1px);
    top: 50%;
    transform: translateY(-50%);
    border: 4px solid transparent;
    border-right-color: ${theme.colors.surface};
  }
`;

const Label = styled.span`
  display: block;
  background: ${theme.colors.surface};
  border: 1px solid ${theme.colors.accentMuted};
  box-shadow:
    0 0 0 1px ${theme.colors.borderSubtle},
    0 8px 32px rgba(0, 0, 0, 0.5);
  color: ${theme.colors.mainText};
  font-size: 12px;
  font-weight: 500;
  font-family: ${theme.typography.fontFamily};
  letter-spacing: 0.01em;
  padding: 5px 10px;
  border-radius: ${theme.borderRadius.md};
  white-space: nowrap;
  backdrop-filter: blur(8px);
`;

interface TooltipProps {
  label: string;
  children: React.ReactElement;
}

export function Tooltip({ label, children }: TooltipProps) {
  const [visible, setVisible] = useState(false);

  return React.cloneElement(children, {
    onMouseEnter: (e: React.MouseEvent) => {
      setVisible(true);
      children.props.onMouseEnter?.(e);
    },
    onMouseLeave: (e: React.MouseEvent) => {
      setVisible(false);
      children.props.onMouseLeave?.(e);
    },
    style: { ...children.props.style, position: 'relative' },
    children: (
      <>
        {children.props.children}
        {visible && (
          <Box>
            <Label>{label}</Label>
          </Box>
        )}
      </>
    ),
  });
}

export default Tooltip;
