import React from 'react';
import styled from '@emotion/styled';
import { theme } from '@atlantis/shared';

export type BadgeTone =
  | 'neutral'  // muted bg + muted text  — counters
  | 'live'     // green dot pill        — ONLINE indicators
  | 'film'     // orange uppercase pill — FILME tag
  | 'tv'       // blue uppercase pill   — TV tag
  | 'accent';  // brand-tinted pill     — generic emphasis

interface StyledBadgeProps {
  tone: BadgeTone;
}

const TONE_BG: Record<BadgeTone, string> = {
  neutral: 'rgba(255,255,255,0.06)',
  live:    'rgba(127,183,126,0.16)',
  film:    'rgba(232,154,92,0.18)',
  tv:      'rgba(106,168,216,0.18)',
  accent:  theme.colors.accentMuted,
};

const TONE_FG: Record<BadgeTone, string> = {
  neutral: theme.colors.mainTextMuted,
  live:    theme.colors.success,
  film:    '#e89a5c',
  tv:      '#6aa8d8',
  accent:  theme.colors.accent,
};

const StyledBadge = styled.span<StyledBadgeProps>`
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-family: ${theme.typography.fontFamilyMono};
  font-size: 10px;
  font-weight: ${({ tone }) => (tone === 'film' || tone === 'tv' ? 600 : 500)};
  letter-spacing: ${({ tone }) =>
    tone === 'live' || tone === 'film' || tone === 'tv' ? '1.2px' : '0.6px'};
  text-transform: ${({ tone }) =>
    tone === 'live' || tone === 'film' || tone === 'tv' ? 'uppercase' : 'none'};
  padding: ${({ tone }) =>
    tone === 'film' || tone === 'tv' ? '3px 8px' : '2px 7px'};
  border-radius: ${({ tone }) =>
    tone === 'film' || tone === 'tv' ? theme.borderRadius.sm : '3px'};
  background: ${({ tone }) => TONE_BG[tone]};
  color: ${({ tone }) => TONE_FG[tone]};
`;

const PulseDot = styled.span`
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  display: inline-block;
`;

export interface BadgeProps
  extends Omit<React.HTMLAttributes<HTMLSpanElement>, 'children'> {
  tone?: BadgeTone;
  /** Render a leading dot — auto-inferred for `live`. */
  dot?: boolean;
  children?: React.ReactNode;
}

export function Badge({
  tone = 'neutral',
  dot,
  children,
  ...rest
}: BadgeProps) {
  const showDot = dot ?? tone === 'live';
  return (
    <StyledBadge tone={tone} {...rest}>
      {showDot && <PulseDot />}
      {children}
    </StyledBadge>
  );
}
