import React from 'react';
import styled from '@emotion/styled';
import { theme } from '@atlantis/shared';

const Wrapper = styled.label`
  display: flex;
  align-items: center;
  gap: 10px;
  background: ${theme.colors.codeBg};
  border: 1px solid ${theme.colors.border};
  border-radius: ${theme.borderRadius.md};
  padding: 9px 14px;
  transition: border-color ${theme.transitions.fast};

  &:focus-within {
    border-color: ${theme.colors.accent};
  }
`;

const StyledInput = styled.input`
  flex: 1;
  background: transparent;
  border: none;
  outline: none;
  font-family: ${theme.typography.fontFamily};
  font-size: ${theme.typography.fontSizeMd};
  color: ${theme.colors.mainText};
  min-width: 0;

  &::placeholder {
    color: ${theme.colors.mainTextFaint};
  }
`;

const Slot = styled.span`
  display: inline-flex;
  align-items: center;
  color: ${theme.colors.mainTextMuted};
  flex-shrink: 0;
`;

export interface InputProps
  extends React.InputHTMLAttributes<HTMLInputElement> {
  /** Leading slot — usually a search icon. */
  before?: React.ReactNode;
  /** Trailing slot — usually a `<Kbd>⌘K</Kbd>` shortcut hint. */
  after?: React.ReactNode;
}

export const Input = React.forwardRef<HTMLInputElement, InputProps>(
  function Input({ before, after, ...rest }, ref) {
    return (
      <Wrapper>
        {before && <Slot>{before}</Slot>}
        <StyledInput ref={ref} {...rest} />
        {after && <Slot>{after}</Slot>}
      </Wrapper>
    );
  },
);
