import React, { useEffect, useRef, useState } from 'react';
import styled from '@emotion/styled';
import { keyframes } from '@emotion/react';
import { theme } from '@atlantis/shared';
import { Icon } from './Icon';
import type { IconName } from './Icon';

export interface SuiteChild {
  id: string;
  name: string;
  /** Optional emoji or single-char glyph before the name. */
  glyph?: string;
  onClick: () => void;
}

export interface SuiteEntry {
  id: string;
  /** Translated display label. */
  name: string;
  /** Translated short subtitle (e.g. "Saúde · Hábitos"). */
  subtitle?: string;
  /** Suite tint — glyph tile, count chip, dot in the trigger. */
  color: string;
  /** Icon name from `@atlantis/ui` Icon registry (e.g. 'beaker'). */
  icon: IconName;
  /** Number shown in the right-hand chip (apps in the suite). */
  count: number;
  /** Primary click handler — fires when the row is selected. Omit only when
   *  `children` is present AND the parent row itself should not navigate. */
  onClick?: () => void;
  /** If set, the row expands inline to show child entries rather than
   *  navigating on click. Used by the Games suite so individual games stay
   *  searchable through the menu. */
  children?: SuiteChild[];
}

export interface SuitesMenuProps {
  /** Translated label for the trigger button (e.g. "Suítes"). */
  label: string;
  /** Translated aria-label for the parent button. */
  ariaLabel: string;
  /** Translated word for count tooltip — "{N} {appsLabel}". */
  appsLabel: string;
  suites: SuiteEntry[];
}

// ─── Trigger ────────────────────────────────────────────────────────────────

