/**
 * Lightweight Groq chat helper.
 *
 * Key resolution order:
 *   1. Build-time `process.env.GROK_API_KEY` (from the app's .env or shell .env).
 *   2. User-set key in `atlantis:api-keys` (managed by SettingsPage).
 *
 * Returns `null` when no key is configured — callers should hide
 * the Ask affordance entirely in that case.
 */

import { getSetting } from './db';

// DefinePlugin (Webpack) inlines `process.env.*` at build time.
// Declare the relevant keys so TypeScript resolves them without @types/node.
declare const process: { env: { GROK_API_KEY?: string } };

interface ApiKeysSetting {
  groq?: string;
  gemini?: string;
}

const SETTINGS_KEY = 'atlantis:api-keys';
const ENDPOINT = 'https://api.groq.com/openai/v1/chat/completions';
const MODEL = 'llama-3.1-8b-instant';

export async function resolveGroqKey(): Promise<string | null> {
  const envKey = process.env.GROK_API_KEY;
  if (envKey && envKey.length > 0) return envKey;
  try {
    const raw = await getSetting(SETTINGS_KEY);
    if (!raw) return null;
    const parsed: ApiKeysSetting = JSON.parse(raw);
    if (parsed.groq && parsed.groq.length > 0) return parsed.groq;
  } catch {
    /* corrupt or missing */
  }
  return null;
}

export function hasEnvGroqKey(): boolean {
  return !!process.env.GROK_API_KEY && process.env.GROK_API_KEY.length > 0;
}

interface GroqResponse {
  choices?: Array<{ message?: { content?: string } }>;
  error?: { message?: string };
}

export interface GroqMessage {
  role: 'user' | 'assistant';
  content: string;
}

export async function askGroq(
  prompt: string,
  options: {
    key: string;
    system?: string;
    locale?: 'en' | 'pt';
    signal?: AbortSignal;
    /** Previous conversation turns (up to last 6) sent as context. */
    history?: GroqMessage[];
    /** Maximum tokens in the response. Default: 1024. */
    maxTokens?: number;
  },
): Promise<string> {
  const lang = options.locale === 'pt' ? 'Portuguese' : 'English';
  const system =
    options.system ??
    [
      `You are Atlantis, a concise personal-dashboard assistant.`,
      `Answer in ${lang}. Stay focused and reasonably concise.`,
      `If you don't know, say so plainly.`,
      ``,
      `Responses render as rich Markdown in the Atlantis UI. Use these blocks when`,
      `they fit the answer:`,
      `- Headings, bold/italic, bullet & numbered lists, GFM tables and task lists.`,
      `- Fenced code blocks with a language tag (\`\`\`ts / \`\`\`py / \`\`\`sql …).`,
      `- Callouts as blockquotes: \`> [!NOTE]\`, \`> [!TIP]\`, \`> [!IMPORTANT]\`,`,
      `  \`> [!WARNING]\`, \`> [!CAUTION]\`.`,
      `- Diagrams / flowcharts / sequence / pie / gantt: fenced \`\`\`mermaid block`,
      `  (Mermaid 11 syntax).`,
      `- Numeric charts: fenced \`\`\`chart block with \`type: bar|pie|line\`,`,
      `  \`labels: [..]\`, \`data: [..]\`, optional \`title:\` and \`colors:\`.`,
      ``,
      `Default to Mermaid for relationships/flows and \`chart\` for quantitative`,
      `data the user provided. Never use Mermaid for time-series or numeric`,
      `trends (value per year / month / category) — those are always \`chart\`.`,
      `Never emit an empty fenced block. Keep caption text short around rendered blocks.`,
    ].join('\n');

  // Cap history at last 6 turns to keep request size small.
  const historyMessages = (options.history ?? []).slice(-6);

  const res = await fetch(ENDPOINT, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${options.key}`,
    },
    body: JSON.stringify({
      model: MODEL,
      messages: [
        { role: 'system', content: system },
        ...historyMessages,
        { role: 'user', content: prompt },
      ],
      temperature: 0.4,
      max_tokens: options.maxTokens ?? 1024,
    }),
    signal: options.signal,
  });

  const data = (await res.json()) as GroqResponse;
  if (!res.ok) {
    throw new Error(data.error?.message ?? `Groq HTTP ${res.status}`);
  }
  const text = data.choices?.[0]?.message?.content?.trim();
  if (!text) throw new Error('Empty response from Groq');
  return text;
}
